	[21298] = { "Manual of Battle Shout VII", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_03", { "Item Level 60", "Classes: Warrior", "Requires Level 60", "The warrior shouts, increasing the melee attack power of all party members within 20 yards by 140. Lasts 3 min.", "\"Teaches Battle Shout (Rank 7).\"" }, { 1 } },
	[21299] = { "Manual of Revenge VI", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_03", { "Item Level 60", "Classes: Warrior", "Requires Level 60", "Instantly counterattack an enemy for 138 to 168 damage and a high amount of threat. Revenge must follow a block, dodge or parry.", "\"Teaches Revenge (Rank 6).\"" }, { 1 } },
	[21300] = { "Handbook of Backstab IX", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_10", { "Item Level 60", "Classes: Rogue", "Requires Level 60", "Backstab the target, causing 150% weapon damage plus 150 to the target. Must be behind the target. Requires a dagger in the main hand. Awards 1 combo point.", "\"Teaches Backstab (Rank 9).\"" }, { 4 } },
	[21302] = { "Handbook of Deadly Poison V", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_10", { "Item Level 60", "Classes: Rogue", "Requires Level 60", "Coats a weapon with poison that lasts for 30 minutes.", "Each strike has a 30% chance of poisoning the enemy for 92 Nature damage over 12 sec. Stacks up to 5 times on a single target. 180 charges.", "\"Teaches Deadly Poison (Rank 5).\"" }, { 4 } },
	[21303] = { "Handbook of Feint V", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_10", { "Item Level 60", "Classes: Rogue", "Requires Level 60", "Performs a feint, causing no damage but lowering your threat by a large amount, making the enemy less likely to attack you.", "\"Teaches Feint (Rank 5).\"" }, { 4 } },
	[21304] = { "Guide: Multi-Shot V", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_02", { "Item Level 60", "Classes: Hunter", "Requires Level 60", "\"Teaches Multi-Shot (Rank 5).\"" }, { 3 } },
	[21306] = { "Guide: Serpent Sting IX", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_02", { "Item Level 60", "Classes: Hunter", "Requires Level 60", "Stings the target, causing 555 Nature damage over 15 sec. Only one Sting per Hunter can be active on any one target.", "\"Teaches Serpent Sting (Rank 9).\"" }, { 3 } },
	[21307] = { "Guide: Aspect of the Hawk VII", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_book_02", { "Item Level 60", "Classes: Hunter", "Requires Level 60", "The hunter takes on the aspects of a hawk, increasing Ranged Attack Power by 120. Only one Aspect can be active at a time.", "\"Teaches Aspect of the Hawk (Rank 7).\"" }, { 3 } },
	[21321] = { "Red Qiraji Resonating Crystal", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_qirajicrystal_02", { "Item Level 60", "Binds when picked up", "Unique", "Mount (Account-wide)", "Requires Level 60", "|cff1eff00Use: Teaches you how to summon this mount.|r", "Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground." } },
	[21323] = { "Green Qiraji Resonating Crystal", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_qirajicrystal_03", { "Item Level 60", "Binds when picked up", "Unique", "Mount (Account-wide)", "Requires Level 60", "|cff1eff00Use: Teaches you how to summon this mount.|r", "Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground." } },
	[21324] = { "Yellow Qiraji Resonating Crystal", 3, "", 0, "Wowhead, Wowhead Classic", "Interface\\Icons\\inv_misc_qirajicrystal_01", { "Item Level 60", "Binds when picked up", "Unique", "Mount (Account-wide)", "Requires Level 60", "|cff1eff00Use: Teaches you how to summon this mount.|r", "Emits a high frequency sound, forcing a silithid tank to burrow out from its home beneath the Temple of Ahn'Qiraj. The silithid is obedient to the summoner and can be used as a mount within the Temple of Ahn'Qiraj. Any hostile action towards the rider forces the tank underground." } },
